package org.json;import java.util.*;public class JSONObject{final Map<String,Object> v=new LinkedHashMap<>();public JSONObject put(String k,Object x)throws JSONException{v.put(k,x);return this;}public String optString(String k){return optString(k,"");}public String optString(String k,String d){Object x=v.get(k);return x==null?d:String.valueOf(x);}public long optLong(String k){return optLong(k,0);}public long optLong(String k,long d){Object x=v.get(k);return x instanceof Number?((Number)x).longValue():d;}public boolean has(String k){return v.containsKey(k);}public JSONObject copy(){JSONObject o=new JSONObject();o.v.putAll(v);return o;}}